double sign = 1.0;
if (b < a) {
    std::swap(a, b);
    sign = -1.0;
}
double h = (b - a) / static_cast<double>(N);
double sum = 0.0;
for (int i = 0; i < N; ++i) {
    double x = a + h * (i + 0.5);
    sum += f(x);
}
return sign * sum * h;

